(6233360, 921913, 23484, '<td valign="top">I like the way she comes out of the light.</td>', 'I like the way she comes out of the light.', '2010-11-26 00:29:06.000000', NULL, 1),
(6233361, 921983, 23484, '<td valign="top">Almost like the world has been taken over by aliens. Fantastic job.</td>', 'Almost like the world has been taken over by aliens. Fantastic job.', '2010-11-26 00:29:57.000000', NULL, 1),
(6233362, 921865, 23484, '<td valign="top">Very nice. I like the muted colors.</td>', 'Very nice. I like the muted colors.', '2010-11-26 00:30:49.000000', NULL, 1),
(6233371, 921901, 23484, '<td valign="top">Very nice. They just become part of the landscape.</td>', 'Very nice. They just become part of the landscape.', '2010-11-26 00:35:17.000000', NULL, 1),
(6233374, 921919, 23484, '<td valign="top">The starkness really makes this image. Nicely done.</td>', 'The starkness really makes this image. Nicely done.', '2010-11-26 00:36:38.000000', NULL, 1),
(6233388, 921934, 83313, '<td valign="top">A great shot from you, as usual, and I''ll be interested in finding out how you set it all up (My guess is this is upside down from how it was shot). I doubt this is the sort of shot Posthumous would go for, but ya'' never know.</td>', 'A great shot from you, as usual, and I''ll be interested in finding out how you set it all up (My guess is this is upside down from how it was shot). I doubt this is the sort of shot Posthumous would go for, but ya'' never know.', '2010-11-26 00:50:19.000000', NULL, 1),
(6233414, 921424, 96751, '<td valign="top">Nice minimalism, great tones.</td>', 'Nice minimalism, great tones.', '2010-11-26 01:07:57.000000', NULL, 1),
(6233417, 921757, 96751, '<td valign="top">One of my favorite places in the world.  There is nothing like the backstage smell :-)<br/> <br/>What theater is this?  How did you get up on the catwalk?</td>', 'One of my favorite places in the world.  There is nothing like the backstage smell :-) What theater is this?  How did you get up on the catwalk?', '2010-11-26 01:08:36.000000', NULL, 1),
(6233419, 920932, 41337, '<td valign="top">What''s wrong with your camera? Caden and Laine are so blurry. :P</td>', 'What''s wrong with your camera? Caden and Laine are so blurry. :P', '2010-11-26 01:08:51.000000', NULL, 1),
(6233422, 921900, 96751, '<td valign="top">Extremely well done twirl blur.  You captured the surfer square in the center of the "pipeline".</td>', 'Extremely well done twirl blur.  You captured the surfer square in the center of the "pipeline".', '2010-11-26 01:09:17.000000', NULL, 1),
(6233424, 921439, 96751, '<td valign="top">Fun use of the lensbaby.  Great sense of adventure.</td>', 'Fun use of the lensbaby.  Great sense of adventure.', '2010-11-26 01:09:40.000000', NULL, 1),
(6233433, 921873, 96751, '<td valign="top">The blur combine with the soft tones to create a delightful combination of form and movement.</td>', 'The blur combine with the soft tones to create a delightful combination of form and movement.', '2010-11-26 01:13:55.000000', NULL, 1),
(6233434, 921287, 96751, '<td valign="top">Daredevil!!  I love the squiggly streaks.  Just enough information to take us for a joyride.</td>', 'Daredevil!!  I love the squiggly streaks.  Just enough information to take us for a joyride.', '2010-11-26 01:14:53.000000', NULL, 1),
(6233437, 921863, 96751, '<td valign="top">Wow.  I almost didn''t see the guy walking by.  Wicked good.  An echo of what he was once, where he was once.</td>', 'Wow.  I almost didn''t see the guy walking by.  Wicked good.  An echo of what he was once, where he was once.', '2010-11-26 01:15:38.000000', NULL, 1),
(6233442, 921576, 96751, '<td valign="top">Fabulous.  A real slice of life, leaving town.</td>', 'Fabulous.  A real slice of life, leaving town.', '2010-11-26 01:17:21.000000', NULL, 1),
(6233444, 921880, 96751, '<td valign="top">I love the found filter of the screen.  A dance of light around a dark and skinny dancer.</td>', 'I love the found filter of the screen.  A dance of light around a dark and skinny dancer.', '2010-11-26 01:18:00.000000', NULL, 1),
(6233446, 921247, 96751, '<td valign="top">Terrific motion blur, and the colors are terrific.</td>', 'Terrific motion blur, and the colors are terrific.', '2010-11-26 01:18:17.000000', NULL, 1),
(6233449, 921485, 96751, '<td valign="top">I love these fountains, and shooting this at night shows them (and the child) off to perfection.</td>', 'I love these fountains, and shooting this at night shows them (and the child) off to perfection.', '2010-11-26 01:18:54.000000', NULL, 1),
(6233451, 921801, 96751, '<td valign="top">So serene and geometric.</td>', 'So serene and geometric.', '2010-11-26 01:19:09.000000', NULL, 1),
(6233454, 921869, 96751, '<td valign="top">MASTERFULLY processed.  These double escalators are so photogenic anyway, but this deep sepia, and the graininess, combined with the metallic tones and the uncertain but bright exit make this an exquisite entry.  Thank you!</td>', 'MASTERFULLY processed.  These double escalators are so photogenic anyway, but this deep sepia, and the graininess, combined with the metallic tones and the uncertain but bright exit make this an exquisite entry.  Thank you!', '2010-11-26 01:20:13.000000', NULL, 1),
(6233457, 921107, 96751, '<td valign="top">Wonderful pov, and the spiral is very enticing.  I think the motion blur may have been more effective if the closer elements with in sharp focus.  Good choice of b/w.</td>', 'Wonderful pov, and the spiral is very enticing.  I think the motion blur may have been more effective if the closer elements with in sharp focus.  Good choice of b/w.', '2010-11-26 01:21:08.000000', NULL, 1),
(6233459, 921892, 96751, '<td valign="top">Very delicate and lovely.</td>', 'Very delicate and lovely.', '2010-11-26 01:21:26.000000', NULL, 1),
(6233462, 921546, 96751, '<td valign="top">And Johnathan Livingston Duck observed the rest of his brethren zigged and zagged about, oblivious to the majesty of the setting sun.  He did not notice Jacqueline Livingston Duck observing him.</td>', 'And Johnathan Livingston Duck observed the rest of his brethren zigged and zagged about, oblivious to the majesty of the setting sun.  He did not notice Jacqueline Livingston Duck observing him.', '2010-11-26 01:22:58.000000', NULL, 1),
(6233467, 921974, 96751, '<td valign="top">Oh come ON!  A sunbeam ON the egret????  This is just too marvelous.  It is amazing how the jogger and the dog - arguably the predominant subjects - are second to the first two elements.  Beautiful parallel lines.</td>', 'Oh come ON!  A sunbeam ON the egret????  This is just too marvelous.  It is amazing how the jogger and the dog - arguably the predominant subjects - are second to the first two elements.  Beautiful parallel lines.', '2010-11-26 01:24:14.000000', NULL, 1),
(6233469, 921844, 96751, '<td valign="top">we were... Forest Gump?  Sorry, that white feather just took me there.  Very dark and moody, and thought-provoking.</td>', 'we were... Forest Gump?  Sorry, that white feather just took me there.  Very dark and moody, and thought-provoking.', '2010-11-26 01:25:01.000000', NULL, 1),
(6233472, 921816, 96751, '<td valign="top">There is an eye in every room, in every structure, in every heart, that sees everything.  Very cool.</td>', 'There is an eye in every room, in every structure, in every heart, that sees everything.  Very cool.', '2010-11-26 01:25:37.000000', NULL, 1),
(6233474, 921923, 96751, '<td valign="top">Beautiful and tender, a melody of soft colors.</td>', 'Beautiful and tender, a melody of soft colors.', '2010-11-26 01:25:57.000000', NULL, 1),
(6233479, 921901, 96751, '<td valign="top">Sigh.  I''m going to have to get a lensbaby...  I love the darkness of the silhouettes against the whiteness of everything else, and just that patch of stirred sand, where a happy  moment was just recently shared.</td>', 'Sigh.  I''m going to have to get a lensbaby...  I love the darkness of the silhouettes against the whiteness of everything else, and just that patch of stirred sand, where a happy  moment was just recently shared.', '2010-11-26 01:27:00.000000', NULL, 1),
(6233483, 921335, 96751, '<td valign="top">There is a foreboding that informs this image, he faces the darker side of the day, where there is nothing.</td>', 'There is a foreboding that informs this image, he faces the darker side of the day, where there is nothing.', '2010-11-26 01:28:00.000000', NULL, 1),
(6233486, 921895, 96751, '<td valign="top">Exceptional framing!!!</td>', 'Exceptional framing!!!', '2010-11-26 01:28:21.000000', NULL, 1),
(6233487, 921297, 96751, '<td valign="top">Languid and beautiful.</td>', 'Languid and beautiful.', '2010-11-26 01:28:36.000000', NULL, 1),
(6233489, 920851, 96751, '<td valign="top">Oh, this is so wonderful.  Your title is inspired.</td>', 'Oh, this is so wonderful.  Your title is inspired.', '2010-11-26 01:28:59.000000', NULL, 1),
(6233490, 920872, 96751, '<td valign="top">Indeed!  Haunting...</td>', 'Indeed!  Haunting...', '2010-11-26 01:29:18.000000', NULL, 1),
(6233492, 921329, 96751, '<td valign="top">I''m not crazy about the ghosting around the edges of whatever that is, but the colors are fabulous.</td>', 'I''m not crazy about the ghosting around the edges of whatever that is, but the colors are fabulous.', '2010-11-26 01:30:03.000000', NULL, 1),
(6233493, 921422, 96751, '<td valign="top">Lovely minimalism.</td>', 'Lovely minimalism.', '2010-11-26 01:30:21.000000', NULL, 1),
(6233495, 920914, 96751, '<td valign="top">Like a Renoir pastel, without my eyeglasses.  A delicate and ghostly image.  Beautiful.</td>', 'Like a Renoir pastel, without my eyeglasses.  A delicate and ghostly image.  Beautiful.', '2010-11-26 01:30:54.000000', NULL, 1),
(6233499, 921965, 96751, '<td valign="top">Oh, the tones are delicious, and that twig on the left looks like a dancer trying to touch the downy ground with the tips of her toes.  An image that inspires the imagination.</td>', 'Oh, the tones are delicious, and that twig on the left looks like a dancer trying to touch the downy ground with the tips of her toes.  An image that inspires the imagination.', '2010-11-26 01:32:15.000000', NULL, 1),
(6233505, 921804, 96751, '<td valign="top">Wow.  This is so good.  The "loser" seems sooooo faaaaar awaaaaay, and the standing "victor" sooooo taaaaall!!  Normally, the chairs and fans and other elements would be distracting, but they propose a prison of vertical lines, caging in the opponents.  Marvelous.</td>', 'Wow.  This is so good.  The "loser" seems sooooo faaaaar awaaaaay, and the standing "victor" sooooo taaaaall!!  Normally, the chairs and fans and other elements would be distracting, but they propose a prison of vertical lines, caging in the opponents.  Marvelous.', '2010-11-26 01:34:03.000000', NULL, 1),
(6233509, 921798, 96751, '<td valign="top">Beautifully done.  Great use of zoom to emphasize the ghostly nature of the transparent tree.</td>', 'Beautifully done.  Great use of zoom to emphasize the ghostly nature of the transparent tree.', '2010-11-26 01:35:35.000000', NULL, 1),
(6233510, 921512, 96751, '<td valign="top">Beautiful.  Could have been interesting rotated 180...</td>', 'Beautiful.  Could have been interesting rotated 180...', '2010-11-26 01:36:01.000000', NULL, 1),
(6233513, 921744, 96751, '<td valign="top">Poor thing.  He looks so disheartened, with his antennae drooping like that.  Like he just realize how far he still has to go.  Stunning detail in such a shallow dof.  And the colors and lighting are stellar.</td>', 'Poor thing.  He looks so disheartened, with his antennae drooping like that.  Like he just realize how far he still has to go.  Stunning detail in such a shallow dof.  And the colors and lighting are stellar.', '2010-11-26 01:36:59.000000', NULL, 1),
(6233515, 921884, 96751, '<td valign="top">An outtake from ET?  Weird and interesting.</td>', 'An outtake from ET?  Weird and interesting.', '2010-11-26 01:37:22.000000', NULL, 1),
(6233516, 921951, 96751, '<td valign="top">Straight out of Spy vs. Spy.</td>', 'Straight out of Spy vs. Spy.', '2010-11-26 01:37:36.000000', NULL, 1),
(6233517, 921983, 96751, '<td valign="top">Nice use of selective desat.  Great long shadows.</td>', 'Nice use of selective desat.  Great long shadows.', '2010-11-26 01:37:55.000000', NULL, 1),
(6233519, 920972, 96751, '<td valign="top">Fabulous title.</td>', 'Fabulous title.', '2010-11-26 01:38:13.000000', NULL, 1),
(6233522, 921163, 96751, '<td valign="top">I can''t believe all those question marks hanging and glowing in the dark.  I love it.  Maybe just a little less black to the right and bottom...</td>', 'I can''t believe all those question marks hanging and glowing in the dark.  I love it.  Maybe just a little less black to the right and bottom...', '2010-11-26 01:39:04.000000', NULL, 1),
(6233532, 921558, 117534, '<td valign="top">Really like this! you nailed sloitude, hope this does well for you!</td>', 'Really like this! you nailed sloitude, hope this does well for you!', '2010-11-26 01:42:20.000000', NULL, 1),
