(6233536, 921871, 96751, '<td valign="top">Quirky and surreal and lovely.</td>', 'Quirky and surreal and lovely.', '2010-11-26 01:42:57.000000', NULL, 1),
(6233541, 921362, 96751, '<td valign="top">OMG!!!!!!!! What a great find.  How fortunate that you looked up.  The sky is fantastic, but those lines of birds - wow.</td>', 'OMG!!!!!!!! What a great find.  How fortunate that you looked up.  The sky is fantastic, but those lines of birds - wow.', '2010-11-26 01:43:50.000000', NULL, 1),
(6233545, 921869, 117534, '<td valign="top">Love this! Your processing is right on the mark for me. Good Luck!</td>', 'Love this! Your processing is right on the mark for me. Good Luck!', '2010-11-26 01:44:32.000000', NULL, 1),
(6233547, 921976, 96751, '<td valign="top">I love the complementary colors here.</td>', 'I love the complementary colors here.', '2010-11-26 01:44:58.000000', NULL, 1),
(6233550, 921910, 117534, '<td valign="top">If this don''t nail a posthumous award I don''t know what does! Excellent</td>', 'If this don''t nail a posthumous award I don''t know what does! Excellent', '2010-11-26 01:45:32.000000', NULL, 1),
(6233554, 921934, 96751, '<td valign="top">I''m not sure this would be considered "posthumous", but stunning work and creativity as usual.  I''ve just started playing with levitation images, and am enjoying trying to figure this out :-)</td>', 'I''m not sure this would be considered "posthumous", but stunning work and creativity as usual.  I''ve just started playing with levitation images, and am enjoying trying to figure this out :-)', '2010-11-26 01:46:12.000000', NULL, 1),
(6233558, 921895, 117534, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2010-11-26 01:46:56.000000', NULL, 1),
(6233560, 921408, 96751, '<td valign="top">Inspired choice to invert this.  There are angels in all dimensions.</td>', 'Inspired choice to invert this.  There are angels in all dimensions.', '2010-11-26 01:47:29.000000', NULL, 1),
(6233563, 921618, 96751, '<td valign="top">This is such a beautiful visual treat.  The colors are just sublime.  I could stare at this for hours, and could easily see this on my wall.</td>', 'This is such a beautiful visual treat.  The colors are just sublime.  I could stare at this for hours, and could easily see this on my wall.', '2010-11-26 01:48:16.000000', NULL, 1),
(6233564, 921366, 96751, '<td valign="top">Freaky scary.</td>', 'Freaky scary.', '2010-11-26 01:48:29.000000', NULL, 1),
(6233565, 921910, 96751, '<td valign="top">Do not adjust your television...  I love how dimensional this is.  Ghostly and solid at the same time.  Love the tones.</td>', 'Do not adjust your television...  I love how dimensional this is.  Ghostly and solid at the same time.  Love the tones.', '2010-11-26 01:49:00.000000', NULL, 1),
(6233567, 921865, 117534, '<td valign="top">GREAT CAPTURE! and love your processing over all just darn fine!!</td>', 'GREAT CAPTURE! and love your processing over all just darn fine!!', '2010-11-26 01:49:11.000000', NULL, 1),
(6233569, 921783, 96751, '<td valign="top">I love how the tendrils seem to glow at the end of the leaf.  Fabulous and original view of a commonly photographed plant.</td>', 'I love how the tendrils seem to glow at the end of the leaf.  Fabulous and original view of a commonly photographed plant.', '2010-11-26 01:51:15.000000', NULL, 1),
(6233572, 921876, 96751, '<td valign="top">I am learning SO much viewing the images in this challenge.  Combining the lensbaby with b/w - this is so inspired and marvelous.  The lighting is just so emotional, and the leading lines of the fence are perfect to lead us through a delightful and rewarding image.  There is something to enjoy everywhere one looks.</td>', 'I am learning SO much viewing the images in this challenge.  Combining the lensbaby with b/w - this is so inspired and marvelous.  The lighting is just so emotional, and the leading lines of the fence are perfect to lead us through a delightful and rewarding image.  There is something to enjoy everywhere one looks.', '2010-11-26 01:52:46.000000', NULL, 1),
(6233573, 921544, 96751, '<td valign="top">Love the three paws in the air.  Great doggie reflection.</td>', 'Love the three paws in the air.  Great doggie reflection.', '2010-11-26 01:53:22.000000', NULL, 1),
(6233574, 921953, 96751, '<td valign="top">ah, a cat picture even PH would love :-)  Wonderful silhouette and colors.  The wiggly lines and circles on the curtain are just icing on the cake.</td>', 'ah, a cat picture even PH would love :-)  Wonderful silhouette and colors.  The wiggly lines and circles on the curtain are just icing on the cake.', '2010-11-26 01:54:19.000000', NULL, 1),
(6233575, 921580, 96751, '<td valign="top">Haunting, marvelous, enigmatic.</td>', 'Haunting, marvelous, enigmatic.', '2010-11-26 01:54:35.000000', NULL, 1),
(6233576, 921892, 117534, '<td valign="top">I bet this will either win or be in the top 3. Very artistic and to me relaxing, really like it!</td>', 'I bet this will either win or be in the top 3. Very artistic and to me relaxing, really like it!', '2010-11-26 01:54:35.000000', NULL, 1),
(6233577, 921928, 117534, '<td valign="top">This is the style I love so I have to give you the blue ... Very nicely done!</td>', 'This is the style I love so I have to give you the blue ... Very nicely done!', '2010-11-26 01:55:40.000000', NULL, 1),
(6233578, 921862, 96751, '<td valign="top">Incongruous and marvelous.  There is so much power in this image, in the explosion of the ocean, in the threatening sky on the horizon, in the man''s relaxed and Quixotic stance with his umbrella in the face of it all.  Sensational.</td>', 'Incongruous and marvelous.  There is so much power in this image, in the explosion of the ocean, in the threatening sky on the horizon, in the man''s relaxed and Quixotic stance with his umbrella in the face of it all.  Sensational.', '2010-11-26 01:56:17.000000', NULL, 1),
(6233579, 921577, 96751, '<td valign="top">Terrific.  I enjoy taking images like this too - the intricacy of life and it''s many winding roads, all of us living at the same time on different levels with different journeys, sharing space.</td>', 'Terrific.  I enjoy taking images like this too - the intricacy of life and it''s many winding roads, all of us living at the same time on different levels with different journeys, sharing space.', '2010-11-26 01:57:24.000000', NULL, 1),
(6233580, 921513, 96751, '<td valign="top">Enigmatic, delicate, lovely.</td>', 'Enigmatic, delicate, lovely.', '2010-11-26 01:57:50.000000', NULL, 1),
(6233583, 921836, 96751, '<td valign="top">Oh wow.  Love it.</td>', 'Oh wow.  Love it.', '2010-11-26 01:58:08.000000', NULL, 1),
(6233584, 921934, 41337, '<td valign="top">Should be interesting to see how this does. Reminds me of Sam Taylor Wood.</td>', 'Should be interesting to see how this does. Reminds me of Sam Taylor Wood.', '2010-11-26 01:58:26.000000', NULL, 1),
(6233585, 921273, 96751, '<td valign="top">Wonderful street scene.</td>', 'Wonderful street scene.', '2010-11-26 01:58:40.000000', NULL, 1),
