(6233746, 921876, 18655, '<td valign="top">Nicely done. The dark tones and processing suits it well. 7</td>', 'Nicely done. The dark tones and processing suits it well. 7', '2010-11-26 05:09:29.000000', NULL, 1),
(6233747, 921958, 18655, '<td valign="top">Perfect angle and lenghth of the lens for this shot. Processing is great and IMO not over done. 8</td>', 'Perfect angle and lenghth of the lens for this shot. Processing is great and IMO not over done. 8', '2010-11-26 05:10:39.000000', NULL, 1),
(6233748, 921906, 18655, '<td valign="top">Interesting shot with the shadow and the non-shadow person following. 7</td>', 'Interesting shot with the shadow and the non-shadow person following. 7', '2010-11-26 05:11:44.000000', NULL, 1),
(6233749, 921895, 18655, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2010-11-26 05:12:17.000000', NULL, 1),
(6233750, 920972, 18655, '<td valign="top">Not bad... good processing, sharp. I like the series of posters and how all of them are the same but different. But doesn''t do a lot for me otherwise. 6</td>', 'Not bad... good processing, sharp. I like the series of posters and how all of them are the same but different. But doesn''t do a lot for me otherwise. 6', '2010-11-26 05:14:03.000000', NULL, 1),
(6233751, 921900, 18655, '<td valign="top">Great effect totally in line with what the objective is with the sport itself - being in the tunnels (or whatever they call it). Overall very well done! 9</td>', 'Great effect totally in line with what the objective is with the sport itself - being in the tunnels (or whatever they call it). Overall very well done! 9', '2010-11-26 05:15:52.000000', NULL, 1),
(6233752, 921163, 18655, '<td valign="top">Weird effect. Very different but looks good.</td>', 'Weird effect. Very different but looks good.', '2010-11-26 05:16:45.000000', NULL, 1),
(6233754, 921929, 18655, '<td valign="top">This is a little too obscure for me. It looks nice in a way but I just can''t make anything out of it. I may not need to, but there need to be an underlying reason for me to see the reason for chaos. 5</td>', 'This is a little too obscure for me. It looks nice in a way but I just can''t make anything out of it. I may not need to, but there need to be an underlying reason for me to see the reason for chaos. 5', '2010-11-26 05:18:16.000000', NULL, 1),
(6233755, 921804, 18655, '<td valign="top">Well done! The dark tones and b/w goes well with it. Also illustrative. 8</td>', 'Well done! The dark tones and b/w goes well with it. Also illustrative. 8', '2010-11-26 05:19:22.000000', NULL, 1),
(6233756, 921863, 18655, '<td valign="top">Great image and motion. 7</td>', 'Great image and motion. 7', '2010-11-26 05:19:52.000000', NULL, 1),
(6233757, 921957, 18655, '<td valign="top">Not sure what you did or how it''s done. What I AM sure of however is that I love it. The colors, shapes, swirl and everything. 9</td>', 'Not sure what you did or how it''s done. What I AM sure of however is that I love it. The colors, shapes, swirl and everything. 9', '2010-11-26 05:25:37.000000', NULL, 1),
(6233758, 921422, 18655, '<td valign="top">Too bad the negative space is totally white. Otherwise interesting.</td>', 'Too bad the negative space is totally white. Otherwise interesting.', '2010-11-26 05:26:06.000000', NULL, 1),
(6233759, 921960, 18655, '<td valign="top">Not a typical posthumous winner but nice landscape shot.</td>', 'Not a typical posthumous winner but nice landscape shot.', '2010-11-26 05:26:28.000000', NULL, 1),
(6233760, 921297, 18655, '<td valign="top">Of course, there HAD to be some bubbles. But this is nicely dine in the spirit of the challenge.</td>', 'Of course, there HAD to be some bubbles. But this is nicely dine in the spirit of the challenge.', '2010-11-26 05:27:07.000000', NULL, 1),
