(6233786, 921758, 23484, '<td valign="top">Abstract is definitely the word. Interesting.</td>', 'Abstract is definitely the word. Interesting.', '2010-11-26 07:23:31.000000', NULL, 1),
(6233787, 921806, 23484, '<td valign="top">This one is certainly high on the humor scale.</td>', 'This one is certainly high on the humor scale.', '2010-11-26 07:25:28.000000', NULL, 1),
