(6233790, 921163, 23484, '<td valign="top">I would say very questionable. That''s neat.</td>', 'I would say very questionable. That''s neat.', '2010-11-26 07:27:35.000000', NULL, 1),
(6233794, 921544, 23484, '<td valign="top">The reflection is neat.  I usually like higher contrast but this is nice.</td>', 'The reflection is neat.  I usually like higher contrast but this is nice.', '2010-11-26 07:30:59.000000', NULL, 1),
