(6233798, 921912, 23484, '<td valign="top">I don''t know about Jupiter but it certainly looks like a cauldron.</td>', 'I don''t know about Jupiter but it certainly looks like a cauldron.', '2010-11-26 07:37:36.000000', NULL, 1),
(6233799, 921917, 23484, '<td valign="top">Nice colors and I like the placement of the main subject so deep in the corner.</td>', 'Nice colors and I like the placement of the main subject so deep in the corner.', '2010-11-26 07:38:37.000000', NULL, 1),
(6233800, 920887, 23484, '<td valign="top">Since we mostly see these in color here at DPC, it''s interesting to see this in B&amp;W.</td>', 'Since we mostly see these in color here at DPC, it''s interesting to see this in B&W.', '2010-11-26 07:39:24.000000', NULL, 1),
(6233801, 921771, 23484, '<td valign="top">This creates some very neat reflections.</td>', 'This creates some very neat reflections.', '2010-11-26 07:40:06.000000', NULL, 1),
(6233803, 921199, 23484, '<td valign="top">The motion combined with the soft focus gives this a neat effect.</td>', 'The motion combined with the soft focus gives this a neat effect.', '2010-11-26 07:41:06.000000', NULL, 1),
(6233821, 921869, 68020, '<td valign="top">HAHA! - 7</td>', 'HAHA! - 7', '2010-11-26 07:59:47.000000', NULL, 1),
(6233824, 921951, 68020, '<td valign="top">I love the irony! - 8</td>', 'I love the irony! - 8', '2010-11-26 08:03:52.000000', NULL, 1),
(6233857, 921439, 18655, '<td valign="top">It''s amazing how you with focus/blur control managed to get this to look like a 3-D image with no need for special glasses. 8</td>', 'It''s amazing how you with focus/blur control managed to get this to look like a 3-D image with no need for special glasses. 8', '2010-11-26 08:50:01.000000', NULL, 1),
(6233860, 921429, 18655, '<td valign="top">Nicely done. The diagonal lines in combination with the movement and rushing people looks good.</td>', 'Nicely done. The diagonal lines in combination with the movement and rushing people looks good.', '2010-11-26 09:00:11.000000', NULL, 1),
(6233862, 921576, 18655, '<td valign="top">C-130? Interesting shot. The diagonal looks good. Wish I had seen a little more but I do like it.</td>', 'C-130? Interesting shot. The diagonal looks good. Wish I had seen a little more but I do like it.', '2010-11-26 09:01:16.000000', NULL, 1),
(6233864, 921974, 18655, '<td valign="top">Beautiful Contre Jour shot. Strange how the one and only  sun beam is hitting the bird but I like it a lot. 8</td>', 'Beautiful Contre Jour shot. Strange how the one and only  sun beam is hitting the bird but I like it a lot. 8', '2010-11-26 09:06:13.000000', NULL, 1),
(6233865, 921935, 18655, '<td valign="top">I little over done to some maybe. But it suits this picture and I like it a lot. 8</td>', 'I little over done to some maybe. But it suits this picture and I like it a lot. 8', '2010-11-26 09:06:49.000000', NULL, 1),
(6233867, 920887, 18655, '<td valign="top">Hehe - the bird actually does look frozen too. Nicely done! 7</td>', 'Hehe - the bird actually does look frozen too. Nicely done! 7', '2010-11-26 09:07:33.000000', NULL, 1),
(6233870, 921921, 18655, '<td valign="top">Lovely tones, shapes and quality on this. I still miss the message but like it anyway.</td>', 'Lovely tones, shapes and quality on this. I still miss the message but like it anyway.', '2010-11-26 09:11:04.000000', NULL, 1),
(6233871, 921902, 18655, '<td valign="top">This is what I''m looking for. Amazing shot with a frame that suits it well. Great diagonal and contrasts. 9</td>', 'This is what I''m looking for. Amazing shot with a frame that suits it well. Great diagonal and contrasts. 9', '2010-11-26 09:12:09.000000', NULL, 1),
(6233873, 921424, 18655, '<td valign="top">I love abstracts and many similar images. But although you might have some deep thoughts behind the composition and subject here, I  have difficulties seeing it. 5. sorry...</td>', 'I love abstracts and many similar images. But although you might have some deep thoughts behind the composition and subject here, I  have difficulties seeing it. 5. sorry...', '2010-11-26 09:13:30.000000', NULL, 1),
(6233874, 921580, 18655, '<td valign="top">Excellent set-up and interpretation. I love everything about it. No need to dissect it. 10</td>', 'Excellent set-up and interpretation. I love everything about it. No need to dissect it. 10', '2010-11-26 09:15:10.000000', NULL, 1),
(6233875, 921910, 18655, '<td valign="top">Almost looks like a super magnification of fabric. Colors are flowing well.</td>', 'Almost looks like a super magnification of fabric. Colors are flowing well.', '2010-11-26 09:15:50.000000', NULL, 1),
(6233877, 921816, 18655, '<td valign="top">Not sure what it is but is it a nice combination of lines and curves. The subtle colors help as well. Great job!</td>', 'Not sure what it is but is it a nice combination of lines and curves. The subtle colors help as well. Great job!', '2010-11-26 09:20:04.000000', NULL, 1),
(6233879, 921577, 18655, '<td valign="top">Interesting viewpoint and nicely done. The dark tones suits the scene well.</td>', 'Interesting viewpoint and nicely done. The dark tones suits the scene well.', '2010-11-26 09:20:44.000000', NULL, 1),
(6233883, 921719, 18655, '<td valign="top">This almost gives me an eye sore. Might be a little overdone to my liking but better for others. The colors are great though.</td>', 'This almost gives me an eye sore. Might be a little overdone to my liking but better for others. The colors are great though.', '2010-11-26 09:30:09.000000', NULL, 1),
(6233885, 921886, 18655, '<td valign="top">A nice portrait (SP?). Very up close and personal and a little different.</td>', 'A nice portrait (SP?). Very up close and personal and a little different.', '2010-11-26 09:30:56.000000', NULL, 1),
(6233886, 921758, 18655, '<td valign="top">A little messy but otherwise nice shapes and vibrant colors.</td>', 'A little messy but otherwise nice shapes and vibrant colors.', '2010-11-26 09:31:24.000000', NULL, 1),
(6233887, 921932, 18655, '<td valign="top">Great job. The contrasts in combination with the dark tomes makes this a great image for me. I like it a lot! 8</td>', 'Great job. The contrasts in combination with the dark tomes makes this a great image for me. I like it a lot! 8', '2010-11-26 09:32:07.000000', NULL, 1),
(6233888, 921181, 18655, '<td valign="top">Not my cup of tea - sorry...</td>', 'Not my cup of tea - sorry...', '2010-11-26 09:32:28.000000', NULL, 1),
