(6235683, 920852, 30364, '<td valign="top">Well it''s been done before, but rarely this well in my recollection.  Thank you.</td>', 'Well it''s been done before, but rarely this well in my recollection.  Thank you.', '2010-11-28 03:58:05.000000', NULL, 1),
(6235685, 921366, 30364, '<td valign="top">This is so nasty it''s good.  For some reason I expect this guy to speak in an Irish accent.  That alone''s worth a 7.  Thank you.</td>', 'This is so nasty it''s good.  For some reason I expect this guy to speak in an Irish accent.  That alone''s worth a 7.  Thank you.', '2010-11-28 03:59:54.000000', NULL, 1),
(6235686, 921862, 30364, '<td valign="top">Decent photograph, actually a very good photograph, but just a little bit too readily comprehensible for me :)<br/>But I still enjoyed it, thank you.  7.</td>', 'Decent photograph, actually a very good photograph, but just a little bit too readily comprehensible for me :)But I still enjoyed it, thank you.  7.', '2010-11-28 04:01:41.000000', NULL, 1),
(6235687, 921889, 30364, '<td valign="top">You''re too weird even for me.  That''s alarming and probably indicates some kind of therapy is wise.  Nevertheless, 7 and a thank you for the mallet blow to my imagination.</td>', 'You''re too weird even for me.  That''s alarming and probably indicates some kind of therapy is wise.  Nevertheless, 7 and a thank you for the mallet blow to my imagination.', '2010-11-28 04:04:17.000000', NULL, 1),
