(6235801, 921910, 81362, '<td valign="top">Love the complexity emerging from such simple shapes and limited colors. The sense of depth and motion evoke compounded feelings -- mixture of peace and beauty with hint of mystery and perhaps sadness. Excellent image.</td>', 'Love the complexity emerging from such simple shapes and limited colors. The sense of depth and motion evoke compounded feelings -- mixture of peace and beauty with hint of mystery and perhaps sadness. Excellent image.', '2010-11-28 07:46:55.000000', NULL, 1),
(6235802, 921869, 81362, '<td valign="top">Generates thoughts of the ordinary transitioning to the sublime (one of the best reasons for making an image). Placing this very high in my scores.</td>', 'Generates thoughts of the ordinary transitioning to the sublime (one of the best reasons for making an image). Placing this very high in my scores.', '2010-11-28 07:51:02.000000', NULL, 1),
