(6235920, 921951, 54645, '<td valign="top">It''s like a polaroid...adds to the obvious humor.</td>', 'It''s like a polaroid...adds to the obvious humor.', '2010-11-28 10:55:01.000000', NULL, 1),
(6235921, 921809, 1024, '<td valign="top">Great use of negative space, and in spite of that I feel like the bid is right in my face.  Very well done.</td>', 'Great use of negative space, and in spite of that I feel like the bid is right in my face.  Very well done.', '2010-11-28 10:55:06.000000', NULL, 1),
