(6235944, 921984, 106910, '<td valign="top">I really like the colors/monochrome effect w/ this photo</td>', 'I really like the colors/monochrome effect w/ this photo', '2010-11-28 11:12:51.000000', NULL, 1),
(6235946, 921964, 23484, '<td valign="top">Definitely looks like the end of its time.</td>', 'Definitely looks like the end of its time.', '2010-11-28 11:13:44.000000', NULL, 1),
(6235947, 921558, 106910, '<td valign="top">I think the noise is just a bit too much - but doesn''t destroy the photo. I love the background and the way the photo is weighed towards the right but, I don''t believe the title fits for that reason. I still like it. 7</td>', 'I think the noise is just a bit too much - but doesn''t destroy the photo. I love the background and the way the photo is weighed towards the right but, I don''t believe the title fits for that reason. I still like it. 7', '2010-11-28 11:14:23.000000', NULL, 1),
(6235949, 921902, 106910, '<td valign="top">Nice lines - but the border is almost as much an element to this photo as the photo itself. 6</td>', 'Nice lines - but the border is almost as much an element to this photo as the photo itself. 6', '2010-11-28 11:15:04.000000', NULL, 1),
(6235955, 921871, 30982, '<td valign="top">Violation of the art rule!  I know because Ben thinks the leaf is real!  (Comment only.)  P.S. I hope you like this at least a little.  It really is an enjoyable photograph!</td>', 'Violation of the art rule!  I know because Ben thinks the leaf is real!  (Comment only.)  P.S. I hope you like this at least a little.  It really is an enjoyable photograph!', '2010-11-28 11:17:21.000000', NULL, 1),
(6235956, 921915, 23484, '<td valign="top">Very nice golden colors. I like the perspective you got this from.</td>', 'Very nice golden colors. I like the perspective you got this from.', '2010-11-28 11:17:26.000000', NULL, 1),
(6235958, 921929, 23484, '<td valign="top">It looks like arrows pointing to the action.</td>', 'It looks like arrows pointing to the action.', '2010-11-28 11:18:07.000000', NULL, 1),
