(6235963, 921930, 23484, '<td valign="top">Very nice peaceful image. Late night, no more customers, playing his music.</td>', 'Very nice peaceful image. Late night, no more customers, playing his music.', '2010-11-28 11:19:22.000000', NULL, 1),
(6235965, 921932, 23484, '<td valign="top">What a great shot. Love the perspective and the grain.</td>', 'What a great shot. Love the perspective and the grain.', '2010-11-28 11:19:55.000000', NULL, 1),
