INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6235985, 921729, 106910, '<td valign="top">Only one way to heaven... and it leads you to three ways out? I feel like i need to go to see some counseling now...</td>', 'Only one way to heaven... and it leads you to three ways out? I feel like i need to go to see some counseling now...', '2010-11-28 11:36:03.000000', NULL, 1),
(6235987, 921577, 106910, '<td valign="top">this is epic - the title makes it even more so. 9</td>', 'this is epic - the title makes it even more so. 9', '2010-11-28 11:37:54.000000', NULL, 1),
(6235988, 921546, 106910, '<td valign="top">The standing duck makes the photo... it''s like watching one of those time-lapse music videos where the singer is in real-time, but instead... ducks. Quack. 8</td>', 'The standing duck makes the photo... it''s like watching one of those time-lapse music videos where the singer is in real-time, but instead... ducks. Quack. 8', '2010-11-28 11:38:45.000000', NULL, 1),
(6235989, 921362, 106910, '<td valign="top">Not entirely sure the oversaturation/topaz-effect of the clouds works here completely - but I love this shot too much to dislike the processing. Honestly - with this type of shot, I would have gone with a high contrast b/w. 9</td>', 'Not entirely sure the oversaturation/topaz-effect of the clouds works here completely - but I love this shot too much to dislike the processing. Honestly - with this type of shot, I would have gone with a high contrast b/w. 9', '2010-11-28 11:39:47.000000', NULL, 1),
(6235992, 921862, 106910, '<td valign="top">So much action - but the noise in the clouds distracts, but not enough to take away from the photo. 9</td>', 'So much action - but the noise in the clouds distracts, but not enough to take away from the photo. 9', '2010-11-28 11:39:55.000000', NULL, 1),
(6235993, 921804, 106910, '<td valign="top">Vertigo much? Great perspective! 9</td>', 'Vertigo much? Great perspective! 9', '2010-11-28 11:39:59.000000', NULL, 1),
(6235994, 921983, 106910, '<td valign="top">I had to come back to this photo - I love the effect you created w/ the black silhouettes/white lines/blue bag. Artistic and great. 9</td>', 'I had to come back to this photo - I love the effect you created w/ the black silhouettes/white lines/blue bag. Artistic and great. 9', '2010-11-28 11:40:01.000000', NULL, 1),
(6235998, 921895, 106910, '<td valign="top">The framing of this shot is superb</td>', 'The framing of this shot is superb', '2010-11-28 11:43:02.000000', NULL, 1),
(6236003, 921121, 106910, '<td valign="top">This photo would have had a huge effect had the chair been more noticeable (whiter) - otherwise it just looks dark and has no visual impact. 6</td>', 'This photo would have had a huge effect had the chair been more noticeable (whiter) - otherwise it just looks dark and has no visual impact. 6', '2010-11-28 11:44:16.000000', NULL, 1),
(6236004, 921291, 76335, '<td valign="top">This does work as a statement about alcoholism. Minor quibble: The bar code is a little too prominent.</td>', 'This does work as a statement about alcoholism. Minor quibble: The bar code is a little too prominent.', '2010-11-28 11:44:32.000000', NULL, 1),
(6236008, 921759, 76335, '<td valign="top">Negative eggs? Interesting idea. I''ll pass.</td>', 'Negative eggs? Interesting idea. I''ll pass.', '2010-11-28 11:49:17.000000', NULL, 1),
(6236014, 921836, 64086, '<td valign="top">Beautiful composition and textures.</td>', 'Beautiful composition and textures.', '2010-11-28 11:58:01.000000', NULL, 1),
(6236015, 921876, 64086, '<td valign="top">Magical lighting.</td>', 'Magical lighting.', '2010-11-28 11:59:42.000000', NULL, 1),
(6236063, 921934, 108069, '<td valign="top">How on earth did you pull this off? Unreal. Lighting is excellent, the background is dream-like. "Always with style" is right. Excellent.</td>', 'How on earth did you pull this off? Unreal. Lighting is excellent, the background is dream-like. "Always with style" is right. Excellent.', '2010-11-28 12:31:57.000000', NULL, 1),
(6236101, 921906, 30049, '<td valign="top">If this hadn''t been overly processed in regards to noise reduction I think it could have held up well in this competition.</td>', 'If this hadn''t been overly processed in regards to noise reduction I think it could have held up well in this competition.', '2010-11-28 12:43:28.000000', NULL, 1),
(6236111, 921869, 22689, '<td valign="top">I like this photo, the sepia tones you have chosen and the light contribute to create a special atmosphere.</td>', 'I like this photo, the sepia tones you have chosen and the light contribute to create a special atmosphere.', '2010-11-28 12:49:36.000000', NULL, 1),
(6236112, 921917, 30049, '<td valign="top">Lovely photo, although you''ve lost detail in the shadows.  What was black and is now sepia toned, appear more like inkblobs (lower right tree line for example).  Somewhat oversharpened also, which makes the foreground grass have speckles and the tree branch intruding on the middle far right is especially prominent as to being excessively sharpened.  Based on what I''m seeing in regards to post-processing this photo may have been a strong candidate for some lightly applied HDR to handle the various ranges of light/dark.<br/> <br/>In a way, it''s a shame that I''ve commented so much on the processing.  The setting is beautiful and the light looks to have been pretty interesting overall.  Would love to see the original on this.</td>', 'Lovely photo, although you''ve lost detail in the shadows.  What was black and is now sepia toned, appear more like inkblobs (lower right tree line for example).  Somewhat oversharpened also, which makes the foreground grass have speckles and the tree branch intruding on the middle far right is especially prominent as to being excessively sharpened.  Based on what I''m seeing in regards to post-processing this photo may have been a strong candidate for some lightly applied HDR to handle the various ranges of light/dark. In a way, it''s a shame that I''ve commented so much on the processing.  The setting is beautiful and the light looks to have been pretty interesting overall.  Would love to see the original on this.', '2010-11-28 12:50:26.000000', NULL, 1),
(6236116, 921686, 30049, '<td valign="top">Wonderful sense of scale and disorientation here.  At first glance I thought this was a rock wall....then I noticed the tree.  Very well seen and captured!</td>', 'Wonderful sense of scale and disorientation here.  At first glance I thought this was a rock wall....then I noticed the tree.  Very well seen and captured!', '2010-11-28 12:52:32.000000', NULL, 1),
(6236121, 921983, 30049, '<td valign="top">Yes!</td>', 'Yes!', '2010-11-28 12:53:36.000000', NULL, 1),
(6236122, 921577, 30049, '<td valign="top">Outstanding comp!  Well done.</td>', 'Outstanding comp!  Well done.', '2010-11-28 12:54:31.000000', NULL, 1),
(6236133, 921835, 22689, '<td valign="top">I like the effect of the soft clouds, they seem to move slowly while the silhouette remains still.<br/>This brings me to memory &amp;#932;&amp;#945; &amp;#928;&amp;#940;&amp;#957;&amp;#964;&amp;#945; &amp;#8165;&amp;#949;&amp;#8150; (ta panta rhei) "everything flows" (Heraclitus).<br/>Very interesting photo who brings the opportunity to meditate.</td>', 'I like the effect of the soft clouds, they seem to move slowly while the silhouette remains still.This brings me to memory &#932;&#945; &#928;&#940;&#957;&#964;&#945; &#8165;&#949;&#8150; (ta panta rhei) "everything flows" (Heraclitus).Very interesting photo who brings the opportunity to meditate.', '2010-11-28 13:07:46.000000', NULL, 1),
(6236161, 921884, 54645, '<td valign="top">The advertisement for credit in the background completes the image.</td>', 'The advertisement for credit in the background completes the image.', '2010-11-28 13:34:10.000000', NULL, 1),
(6236162, 920932, 54645, '<td valign="top">sweet</td>', 'sweet', '2010-11-28 13:34:20.000000', NULL, 1),
