(6236967, 921546, 108069, '<td valign="top">Extremely interesting and artistic photo. The motion blur is sublime (I particularly like the swan that''s looking at itself). Excellent composition and the one duck that stood perfectly still gets a prize for sure. Excellent work.</td>', 'Extremely interesting and artistic photo. The motion blur is sublime (I particularly like the swan that''s looking at itself). Excellent composition and the one duck that stood perfectly still gets a prize for sure. Excellent work.', '2010-11-29 05:48:35.000000', NULL, 1),
(6236969, 921434, 108069, '<td valign="top">Well spotted scene. Creative entry. Poor guy looks a frazzled mess. I love the hole in his shoe.</td>', 'Well spotted scene. Creative entry. Poor guy looks a frazzled mess. I love the hole in his shoe.', '2010-11-29 05:49:57.000000', NULL, 1),
