INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6237208, 921806, 38032, '<td valign="top">quite strange. I would actually prefer this without the color or maybe with a cooler tone overall (it seems a bit warm for what it is) - I''d also like a bit more context and dimension to tell more or a story.<br/>Quite intriguing though I must say - which is worthy of a comment and critique for sure.</td>', 'quite strange. I would actually prefer this without the color or maybe with a cooler tone overall (it seems a bit warm for what it is) - I''d also like a bit more context and dimension to tell more or a story.Quite intriguing though I must say - which is worthy of a comment and critique for sure.', '2010-11-29 10:01:27.000000', NULL, 1),
(6237213, 921804, 38032, '<td valign="top">THis is a real nice POV  We can see the photographer''s foot (I assume) which is actually the most intriguing part since it has mysterious and metaphorical potential. It leaves me wanting a bit more story though.</td>', 'THis is a real nice POV  We can see the photographer''s foot (I assume) which is actually the most intriguing part since it has mysterious and metaphorical potential. It leaves me wanting a bit more story though.', '2010-11-29 10:03:54.000000', NULL, 1),
(6237214, 921984, 38032, '<td valign="top">Leaves me looking for context.</td>', 'Leaves me looking for context.', '2010-11-29 10:04:30.000000', NULL, 1),
(6237220, 921976, 3585, '<td valign="top">It is not so often that overprocessing rhymes with prepossessing &amp; beguiling</td>', 'It is not so often that overprocessing rhymes with prepossessing & beguiling', '2010-11-29 10:11:06.000000', NULL, 1),
(6237235, 921939, 3585, '<td valign="top">This image would make a nice pair with another entry in this challenge "the confiteor". Judeo-Christian gloom &amp; grit at it''s best.</td>', 'This image would make a nice pair with another entry in this challenge "the confiteor". Judeo-Christian gloom & grit at it''s best.', '2010-11-29 10:23:01.000000', NULL, 1),
(6237236, 921871, 76335, '<td valign="top">Very creative and beautifully executed. Judging by the crisp colors, that can''t be the new breed of Polaroid film.</td>', 'Very creative and beautifully executed. Judging by the crisp colors, that can''t be the new breed of Polaroid film.', '2010-11-29 10:23:16.000000', NULL, 1),
(6237238, 921954, 76335, '<td valign="top">The title is silly but the image is sublime.</td>', 'The title is silly but the image is sublime.', '2010-11-29 10:23:37.000000', NULL, 1),
(6237240, 920932, 76335, '<td valign="top">Beautifully done. Not only a warm and sincere candid moment, but executed nicely in what had to be challenging light.</td>', 'Beautifully done. Not only a warm and sincere candid moment, but executed nicely in what had to be challenging light.', '2010-11-29 10:24:33.000000', NULL, 1),
(6237242, 921034, 76335, '<td valign="top">Has quite a visual impact. Beautiful and ugly at the same time. Good for you.</td>', 'Has quite a visual impact. Beautiful and ugly at the same time. Good for you.', '2010-11-29 10:26:28.000000', NULL, 1),
