(6240234, 921558, 50864, '<td valign="top">Love all the empty space and still a place to sit and enjoy it. Really lovely.</td>', 'Love all the empty space and still a place to sit and enjoy it. Really lovely.', '2010-12-01 11:06:51.000000', NULL, 1),
