(6240272, 921983, 50864, '<td valign="top">Great capture. Makes me so happy I wasn''t out shopping that day.  Love the blue bag in the otherwise colorless scene.</td>', 'Great capture. Makes me so happy I wasn''t out shopping that day.  Love the blue bag in the otherwise colorless scene.', '2010-12-01 11:20:59.000000', NULL, 1),
(6240281, 921816, 50864, '<td valign="top">The wonderful lines in this are really enhanced by the beautiful colors and the grainy processing. This should be framed and hanging on a wall.</td>', 'The wonderful lines in this are really enhanced by the beautiful colors and the grainy processing. This should be framed and hanging on a wall.', '2010-12-01 11:30:26.000000', NULL, 1),
