(6240473, 921965, 113591, '<td valign="top">This probably leans more towards a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=54645" rel="nofollow" target="_blank">bspurgeon</a>genre. I still like the photo.</td>', 'This probably leans more towards a  bspurgeongenre. I still like the photo.', '2010-12-01 14:14:37.000000', NULL, 1),
(6240475, 921730, 113591, '<td valign="top">Marvellously confusing 8</td>', 'Marvellously confusing 8', '2010-12-01 14:15:21.000000', NULL, 1),
(6240476, 921863, 113591, '<td valign="top">Nice work gettiing the green to stand out. Creepy as well. Fits challenge nicely for me.</td>', 'Nice work gettiing the green to stand out. Creepy as well. Fits challenge nicely for me.', '2010-12-01 14:16:03.000000', NULL, 1),
