(6240482, 921247, 113591, '<td valign="top">I like it because you got the flow from far right into the left centre right. It draws one in nicely.</td>', 'I like it because you got the flow from far right into the left centre right. It draws one in nicely.', '2010-12-01 14:21:06.000000', NULL, 1),
(6240484, 921961, 113591, '<td valign="top">Such a clever idea, I''m jealous. Bumping up</td>', 'Such a clever idea, I''m jealous. Bumping up', '2010-12-01 14:22:08.000000', NULL, 1),
