(6240491, 921952, 113591, '<td valign="top">Got the colour exactly right.</td>', 'Got the colour exactly right.', '2010-12-01 14:26:45.000000', NULL, 1),
(6240494, 921562, 113591, '<td valign="top">Well seen.</td>', 'Well seen.', '2010-12-01 14:27:49.000000', NULL, 1),
(6240495, 921107, 113591, '<td valign="top">Captured the grittyness well.</td>', 'Captured the grittyness well.', '2010-12-01 14:28:34.000000', NULL, 1),
(6240497, 921956, 113591, '<td valign="top">Weird. But nice. And pretty. Is that possible? Suppose you got a few comments on being in the wrong challenge (Orange).  7</td>', 'Weird. But nice. And pretty. Is that possible? Suppose you got a few comments on being in the wrong challenge (Orange).  7', '2010-12-01 14:31:12.000000', NULL, 1),
(6240510, 921558, 113591, '<td valign="top">Feeling nicely created. Even the sloping horizon adds something.Fits challenge nicely for me.</td>', 'Feeling nicely created. Even the sloping horizon adds something.Fits challenge nicely for me.', '2010-12-01 14:58:50.000000', NULL, 1),
(6240516, 921910, 113591, '<td valign="top">My daughter (Marna) saw her name in there, so you may regard it as a big success! Hehe.</td>', 'My daughter (Marna) saw her name in there, so you may regard it as a big success! Hehe.', '2010-12-01 15:00:17.000000', NULL, 1),
(6240527, 921757, 113591, '<td valign="top">I see this as a beginning of a story. Bumping up</td>', 'I see this as a beginning of a story. Bumping up', '2010-12-01 15:02:48.000000', NULL, 1),
(6240530, 921983, 113591, '<td valign="top">Or blue bag day. 7</td>', 'Or blue bag day. 7', '2010-12-01 15:03:36.000000', NULL, 1),
(6240534, 921329, 113591, '<td valign="top">Good angle and colour. I also like the way that it is already walking out of the shot.</td>', 'Good angle and colour. I also like the way that it is already walking out of the shot.', '2010-12-01 15:05:40.000000', NULL, 1),
(6240541, 921804, 113591, '<td valign="top">I bet one of them is going to be cross with you  for taking and keeping this photo.</td>', 'I bet one of them is going to be cross with you  for taking and keeping this photo.', '2010-12-01 15:08:43.000000', NULL, 1),
(6240546, 921273, 113591, '<td valign="top">Wil you stop talking already! Or I''ll have to take out the violin case. Bumping up</td>', 'Wil you stop talking already! Or I''ll have to take out the violin case. Bumping up', '2010-12-01 15:09:58.000000', NULL, 1),
(6240550, 921434, 113591, '<td valign="top">How well you captured his tenseness - even desperation. Bumping up</td>', 'How well you captured his tenseness - even desperation. Bumping up', '2010-12-01 15:11:31.000000', NULL, 1),
(6240555, 921886, 113591, '<td valign="top">Eeew. Bumping up</td>', 'Eeew. Bumping up', '2010-12-01 15:13:13.000000', NULL, 1),
(6240556, 921978, 113591, '<td valign="top">Just a bit too much dead area in front.</td>', 'Just a bit too much dead area in front.', '2010-12-01 15:14:02.000000', NULL, 1),
(6240563, 921862, 113591, '<td valign="top">Good contrast between the still watcher and the tumelous waves. Bumping up</td>', 'Good contrast between the still watcher and the tumelous waves. Bumping up', '2010-12-01 15:17:25.000000', NULL, 1),
(6240567, 921771, 113591, '<td valign="top">Well seen. Nitpicking: there isn''t a focus point to stop my eyes from wandering all over the photo.</td>', 'Well seen. Nitpicking: there isn''t a focus point to stop my eyes from wandering all over the photo.', '2010-12-01 15:20:12.000000', NULL, 1),
(6240568, 921892, 113591, '<td valign="top">Like a church window. Bumping up</td>', 'Like a church window. Bumping up', '2010-12-01 15:21:13.000000', NULL, 1),
(6240663, 921871, 105697, '<td valign="top">I like this very much. Thanks....RH</td>', 'I like this very much. Thanks....RH', '2010-12-01 16:02:08.000000', NULL, 1),
(6240861, 921907, 76335, '<td valign="top">There''s something really humorous about this that I can''t put my finger on. It''s beautifully framed and the light is perfect.</td>', 'There''s something really humorous about this that I can''t put my finger on. It''s beautifully framed and the light is perfect.', '2010-12-01 18:26:37.000000', NULL, 1),
(6240864, 921742, 76335, '<td valign="top">I like how different elements work together to create this image -- contrejour, a rhythmic backdrop, golden lighting, and an anonymous subject. Nicely done.</td>', 'I like how different elements work together to create this image -- contrejour, a rhythmic backdrop, golden lighting, and an anonymous subject. Nicely done.', '2010-12-01 18:27:55.000000', NULL, 1),
(6240868, 921958, 76335, '<td valign="top">I love how we see two imminent but opposing forces of nature -- growth and decay -- in competition here.</td>', 'I love how we see two imminent but opposing forces of nature -- growth and decay -- in competition here.', '2010-12-01 18:29:42.000000', NULL, 1),
(6240875, 921757, 76335, '<td valign="top">I love the natural framing (from the shadows) and the feeling of depth. The blurred figure makes it feel somehow lonelier than if there had been no one at all in the picture.</td>', 'I love the natural framing (from the shadows) and the feeling of depth. The blurred figure makes it feel somehow lonelier than if there had been no one at all in the picture.', '2010-12-01 18:34:00.000000', NULL, 1),
(6240879, 920851, 76335, '<td valign="top">Really bizarre. I''ve been unsure what to make of this. Humorous, borderline silly, not quite disgusting -- but nothing if not totally unexpected. Hell, who can fault you for it.</td>', 'Really bizarre. I''ve been unsure what to make of this. Humorous, borderline silly, not quite disgusting -- but nothing if not totally unexpected. Hell, who can fault you for it.', '2010-12-01 18:36:29.000000', NULL, 1),
(6240907, 921429, 76335, '<td valign="top">Having trouble connecting with this one. I do wish they were facing the camera at least.</td>', 'Having trouble connecting with this one. I do wish they were facing the camera at least.', '2010-12-01 19:12:31.000000', NULL, 1),
(6240910, 921935, 76335, '<td valign="top">The combination of tomb, sky and clouds give this a strong foreboding quality. I feel that the crop is a little tight.</td>', 'The combination of tomb, sky and clouds give this a strong foreboding quality. I feel that the crop is a little tight.', '2010-12-01 19:15:06.000000', NULL, 1),
(6240911, 921978, 76335, '<td valign="top">Contrast feels a little flat, and I think you could have zoom-blurred a more interesting specimen. I like the sense of adventure that went into creating this though.</td>', 'Contrast feels a little flat, and I think you could have zoom-blurred a more interesting specimen. I like the sense of adventure that went into creating this though.', '2010-12-01 19:16:11.000000', NULL, 1),
(6240978, 921906, 76335, '<td valign="top">I like the idea, but it feels too much like you composed it more with the cropping tool and less with the camera. Definitely in the spirit of this challenge though.</td>', 'I like the idea, but it feels too much like you composed it more with the cropping tool and less with the camera. Definitely in the spirit of this challenge though.', '2010-12-01 19:52:30.000000', NULL, 1),
(6240990, 921273, 76335, '<td valign="top">This just isn''t coming together for me as a good street photograph. The ladies appear to be engaged in nothing more than idle gossip, which would be fine if they were more in focus. And the man is positioned as if to be creepy, but he just doesn''t look that creepy. Also the quality suffers -- I see noise reduction artifacts in the Lady Right''s jacket. <br/> <br/>That said, I thank you for not showing me anyone''s backside -- or someone merely walking by. In that sense, it''s better than half of the street photography I see on the web. Not that I''m any expert. Far from it.</td>', 'This just isn''t coming together for me as a good street photograph. The ladies appear to be engaged in nothing more than idle gossip, which would be fine if they were more in focus. And the man is positioned as if to be creepy, but he just doesn''t look that creepy. Also the quality suffers -- I see noise reduction artifacts in the Lady Right''s jacket.  That said, I thank you for not showing me anyone''s backside -- or someone merely walking by. In that sense, it''s better than half of the street photography I see on the web. Not that I''m any expert. Far from it.', '2010-12-01 19:59:24.000000', NULL, 1),
(6241001, 921923, 76335, '<td valign="top">I''m through 11% of my voting and this is the first image that really strikes a chord with me. The subtle colors and fleeting textures leave much to the imagination. A real treat for the eyes, the mind.</td>', 'I''m through 11% of my voting and this is the first image that really strikes a chord with me. The subtle colors and fleeting textures leave much to the imagination. A real treat for the eyes, the mind.', '2010-12-01 20:06:52.000000', NULL, 1),
(6241007, 921798, 76335, '<td valign="top">Horrifying. Really. (And dig those fractal patterns over the house.)</td>', 'Horrifying. Really. (And dig those fractal patterns over the house.)', '2010-12-01 20:07:34.000000', NULL, 1),
(6241008, 921774, 76335, '<td valign="top">Forcing spring upon fall, eh? You know, it''s not nice to fool Mother Nature. <br/> <br/>Beautiful.</td>', 'Forcing spring upon fall, eh? You know, it''s not nice to fool Mother Nature.  Beautiful.', '2010-12-01 20:07:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6241010, 921961, 76335, '<td valign="top">A beautiful vortex. This effect can look cliche in the wrong hands, but it holds up nicely here.</td>', 'A beautiful vortex. This effect can look cliche in the wrong hands, but it holds up nicely here.', '2010-12-01 20:07:48.000000', NULL, 1),
(6241011, 921953, 76335, '<td valign="top">Haunting. I love the pattern in the curtains which so beautifully complements the outline of the cat.</td>', 'Haunting. I love the pattern in the curtains which so beautifully complements the outline of the cat.', '2010-12-01 20:07:52.000000', NULL, 1),
(6241012, 921964, 76335, '<td valign="top">There shouldn''t be this much energy and movement in an image of dormancy and decay. It feels as though the tree has reached out and given the house two black eyes. An amazing photograph.</td>', 'There shouldn''t be this much energy and movement in an image of dormancy and decay. It feels as though the tree has reached out and given the house two black eyes. An amazing photograph.', '2010-12-01 20:07:56.000000', NULL, 1),
(6241013, 921880, 76335, '<td valign="top">Nature photography should look this good more often. Well conceived. Very intriguing.</td>', 'Nature photography should look this good more often. Well conceived. Very intriguing.', '2010-12-01 20:08:09.000000', NULL, 1),
(6241014, 921558, 76335, '<td valign="top">A portrait of serenity. Rewards the patient viewer. Beautiful.</td>', 'A portrait of serenity. Rewards the patient viewer. Beautiful.', '2010-12-01 20:08:12.000000', NULL, 1),
(6241015, 921181, 76335, '<td valign="top">In something so simple as an unfocused close up of a doll''s head, there''s something haunting and unsettling and -- maybe it''s a stretch -- <i>unnatural</i>. What a wonderfully twisted vision you had for this.</td>', 'In something so simple as an unfocused close up of a doll''s head, there''s something haunting and unsettling and -- maybe it''s a stretch -- unnatural. What a wonderfully twisted vision you had for this.', '2010-12-01 20:08:15.000000', NULL, 1),
(6241018, 921952, 76335, '<td valign="top">Feels unrealistic, unfinished, raw and wrong. The blue is way over the top. For those reasons, I''m at a total loss to explain why it appeals to me so much. (Or maybe I just did.)</td>', 'Feels unrealistic, unfinished, raw and wrong. The blue is way over the top. For those reasons, I''m at a total loss to explain why it appeals to me so much. (Or maybe I just did.)', '2010-12-01 20:08:22.000000', NULL, 1),
(6241019, 920872, 76335, '<td valign="top">It''s hard to tell just whose Gates you crossed. I love the ambiguity.</td>', 'It''s hard to tell just whose Gates you crossed. I love the ambiguity.', '2010-12-01 20:08:27.000000', NULL, 1),
(6241021, 921576, 76335, '<td valign="top">The more I stare at it, the stranger the story it''s trying to tell me becomes. Fantastic.</td>', 'The more I stare at it, the stranger the story it''s trying to tell me becomes. Fantastic.', '2010-12-01 20:09:09.000000', NULL, 1),
(6241022, 921965, 76335, '<td valign="top">A simple subject and a little imagination go a long way to transform a scene. Very nice.</td>', 'A simple subject and a little imagination go a long way to transform a scene. Very nice.', '2010-12-01 20:09:13.000000', NULL, 1),
(6241023, 921580, 76335, '<td valign="top">Bizarre, and I''m a little confused about the story you''re trying to tell. In any case, it''s a good exercise for the imagination and a good fit for this challenge.</td>', 'Bizarre, and I''m a little confused about the story you''re trying to tell. In any case, it''s a good exercise for the imagination and a good fit for this challenge.', '2010-12-01 20:09:16.000000', NULL, 1),
(6241027, 921919, 76335, '<td valign="top">I fear that the magic of this image will be lost on most viewers. But maybe that''s what makes it so right for this challenge. The shadowy bird on the left contrasts sharply with the two crooners and one mourner on the right. The bird in profile in the middle (sorry -- are these swans?) more or less anchors the image. A nicely balanced composition, interesting to look at.</td>', 'I fear that the magic of this image will be lost on most viewers. But maybe that''s what makes it so right for this challenge. The shadowy bird on the left contrasts sharply with the two crooners and one mourner on the right. The bird in profile in the middle (sorry -- are these swans?) more or less anchors the image. A nicely balanced composition, interesting to look at.', '2010-12-01 20:09:47.000000', NULL, 1),
(6241028, 921956, 76335, '<td valign="top">Such intensity. The branches give this context, but only make the background more mysterious. Feels very apocalyptic. Good work.</td>', 'Such intensity. The branches give this context, but only make the background more mysterious. Feels very apocalyptic. Good work.', '2010-12-01 20:09:51.000000', NULL, 1),
(6241029, 921836, 76335, '<td valign="top">Yes! Grounded yet in flight. A beautiful contradiction.</td>', 'Yes! Grounded yet in flight. A beautiful contradiction.', '2010-12-01 20:10:09.000000', NULL, 1),
(6241030, 921921, 76335, '<td valign="top">Noir and painterly. Or maybe it''s charcoal. Wonderful energy in this.</td>', 'Noir and painterly. Or maybe it''s charcoal. Wonderful energy in this.', '2010-12-01 20:10:13.000000', NULL, 1),
(6241031, 921686, 76335, '<td valign="top">Still life on a grander scale than usual. Beautifully done.</td>', 'Still life on a grander scale than usual. Beautifully done.', '2010-12-01 20:10:16.000000', NULL, 1),
(6241032, 921947, 76335, '<td valign="top">Zone plate? Glowing geometry. It''s beautiful.</td>', 'Zone plate? Glowing geometry. It''s beautiful.', '2010-12-01 20:10:22.000000', NULL, 1),
(6241033, 921366, 76335, '<td valign="top">Love the raw intensity here. Feels like a TV still or something up close and candid in an angry crowd (trading floor comes to mind for no good reason). The blur is not only acceptable, it''s necessary.</td>', 'Love the raw intensity here. Feels like a TV still or something up close and candid in an angry crowd (trading floor comes to mind for no good reason). The blur is not only acceptable, it''s necessary.', '2010-12-01 20:10:37.000000', NULL, 1),
(6241034, 920814, 76335, '<td valign="top">I see an elephant. This is really interesting, a treat for the eyes.</td>', 'I see an elephant. This is really interesting, a treat for the eyes.', '2010-12-01 20:10:40.000000', NULL, 1),
(6241035, 921816, 76335, '<td valign="top">Very surreal geometry. Looked like an eye at first glance. I like the deep hues and grain. A worthwhile experiment.</td>', 'Very surreal geometry. Looked like an eye at first glance. I like the deep hues and grain. A worthwhile experiment.', '2010-12-01 20:10:42.000000', NULL, 1),
(6241036, 921939, 76335, '<td valign="top">Daring yet so subtle.</td>', 'Daring yet so subtle.', '2010-12-01 20:10:45.000000', NULL, 1),
(6241037, 921974, 76335, '<td valign="top">Lots of gravity and tension here. I had to view it a few times to appreciate it. Bumping it a point.</td>', 'Lots of gravity and tension here. I had to view it a few times to appreciate it. Bumping it a point.', '2010-12-01 20:10:48.000000', NULL, 1),
(6241039, 921801, 76335, '<td valign="top">This is an outstanding composition. The green buoy and what looks like a passing jet are terrible intruders that find themselves perfectly incorporated into the composition. Simple visual elements perfectly arranged. Strong image.</td>', 'This is an outstanding composition. The green buoy and what looks like a passing jet are terrible intruders that find themselves perfectly incorporated into the composition. Simple visual elements perfectly arranged. Strong image.', '2010-12-01 20:10:50.000000', NULL, 1),
(6241040, 921809, 76335, '<td valign="top">Pure zen. This image calls no attention to itself. The work and subsequent reward is the viewer''s alone.</td>', 'Pure zen. This image calls no attention to itself. The work and subsequent reward is the viewer''s alone.', '2010-12-01 20:10:52.000000', NULL, 1),
(6241043, 921844, 76335, '<td valign="top">You can stop treading water now. This was my highest score given with no comment (until now). Such a beautiful eye you have. This is exquisite. I commented on another image that any further attempt at words would ruin the image for me. The same applies here, so I''ll stop now.</td>', 'You can stop treading water now. This was my highest score given with no comment (until now). Such a beautiful eye you have. This is exquisite. I commented on another image that any further attempt at words would ruin the image for me. The same applies here, so I''ll stop now.', '2010-12-01 20:13:37.000000', NULL, 1),
(6241044, 921901, 76335, '<td valign="top">This feels right on so many levels. Your subjects, reduced to outlines, stand firm against the frenzy of nature surrounding them. The title is a little too suggestive. There''s a sense of unity and bonding -- maybe happiness, but probably something more enduring. The picture reminds me of some of Harry Callahan''s work. This will be high on my list.</td>', 'This feels right on so many levels. Your subjects, reduced to outlines, stand firm against the frenzy of nature surrounding them. The title is a little too suggestive. There''s a sense of unity and bonding -- maybe happiness, but probably something more enduring. The picture reminds me of some of Harry Callahan''s work. This will be high on my list.', '2010-12-01 20:13:39.000000', NULL, 1),
(6241045, 921730, 76335, '<td valign="top">My guess is that this is cutout sans camera. Impressive as usual. In a category all its own. Nine.</td>', 'My guess is that this is cutout sans camera. Impressive as usual. In a category all its own. Nine.', '2010-12-01 20:13:40.000000', NULL, 1),
(6241046, 921910, 76335, '<td valign="top">I love the choreography, the costumes -- the music especially.</td>', 'I love the choreography, the costumes -- the music especially.', '2010-12-01 20:13:42.000000', NULL, 1),
(6241047, 921780, 100831, '<td valign="top">elegant blur.</td>', 'elegant blur.', '2010-12-01 20:15:10.000000', NULL, 1),
(6241048, 921546, 100831, '<td valign="top">funny! love the little blurs</td>', 'funny! love the little blurs', '2010-12-01 20:15:14.000000', NULL, 1),
(6241049, 921742, 100831, '<td valign="top">Light from the Other Side. This is a very strong emotional image. Love it.</td>', 'Light from the Other Side. This is a very strong emotional image. Love it.', '2010-12-01 20:15:21.000000', NULL, 1),
(6241050, 921730, 100831, '<td valign="top">I have not been able to write a comment but it isn''t because I haven''t looked at this a million times. It''s somehow disturbing. Maybe it''s the blankness of non-emotion. and yet it is not without feeling.... those faces... so close but so far from reality. <br/>Or maybe this is just what it says it is.</td>', 'I have not been able to write a comment but it isn''t because I haven''t looked at this a million times. It''s somehow disturbing. Maybe it''s the blankness of non-emotion. and yet it is not without feeling.... those faces... so close but so far from reality. Or maybe this is just what it says it is.', '2010-12-01 20:15:24.000000', NULL, 1),
(6241051, 921199, 100831, '<td valign="top">lovely blur. the color is wonderful. Must be Bach, but I can''t read the German. Six feet play better than four.</td>', 'lovely blur. the color is wonderful. Must be Bach, but I can''t read the German. Six feet play better than four.', '2010-12-01 20:15:29.000000', NULL, 1),
(6241052, 920816, 100831, '<td valign="top">I like the yellow and the diagonal. and the sun. <br/>I see the wonderful wind-ripped figure. <br/>Excellent.</td>', 'I like the yellow and the diagonal. and the sun. I see the wonderful wind-ripped figure. Excellent.', '2010-12-01 20:15:33.000000', NULL, 1),
