(6241618, 921804, 108069, '<td valign="top">Great story here. Love the look on her face. Very cool and interesting shot.</td>', 'Great story here. Love the look on her face. Very cool and interesting shot.', '2010-12-02 04:22:18.000000', NULL, 1),
(6241633, 921558, 113156, '<td valign="top">very peaceful and lonely photo, there''s not much to it but that''s why it comes across so strong, i guess we sometimes feel like that bench, i also love the tones.</td>', 'very peaceful and lonely photo, there''s not much to it but that''s why it comes across so strong, i guess we sometimes feel like that bench, i also love the tones.', '2010-12-02 04:43:54.000000', NULL, 1),
(6241638, 921983, 113156, '<td valign="top">a glimps of something we normally don''t spot as we hurry about our daily lives, the light and the shadows really make this photo stand out for me.</td>', 'a glimps of something we normally don''t spot as we hurry about our daily lives, the light and the shadows really make this photo stand out for me.', '2010-12-02 04:49:06.000000', NULL, 1),
(6241641, 921974, 113156, '<td valign="top">this photo really works for me, the composition is just right, the ray of sun on the heron, the way the dog looks as if its pulling towards the bird, and it all works perfectly in B&amp;W, a big well done from me.</td>', 'this photo really works for me, the composition is just right, the ray of sun on the heron, the way the dog looks as if its pulling towards the bird, and it all works perfectly in B&W, a big well done from me.', '2010-12-02 04:54:26.000000', NULL, 1),
(6241643, 921939, 113156, '<td valign="top">well it least it made me open my dictionary, its rather grim in a good way, i suppose we can''t always shoot happy plasticky scenes and you even got blood on your hands for this one.</td>', 'well it least it made me open my dictionary, its rather grim in a good way, i suppose we can''t always shoot happy plasticky scenes and you even got blood on your hands for this one.', '2010-12-02 05:05:13.000000', NULL, 1),
(6241644, 921869, 113156, '<td valign="top">when we get to the top will we be met by loved ones lost and gone ?. Great photo has a depth to it that is very hard to describe, i''m sure you will do well.</td>', 'when we get to the top will we be met by loved ones lost and gone ?. Great photo has a depth to it that is very hard to describe, i''m sure you will do well.', '2010-12-02 05:10:45.000000', NULL, 1),
