(6241682, 921869, 108069, '<td valign="top">I swear this is the escalator I take to one of my trains to work each day, and for that I want to throw my monitor out the window. On the other had I love this kind of shot, and this is especially interesting with the fade to white. Stairway to heaven perhaps due to maintenance. Awesome.</td>', 'I swear this is the escalator I take to one of my trains to work each day, and for that I want to throw my monitor out the window. On the other had I love this kind of shot, and this is especially interesting with the fade to white. Stairway to heaven perhaps due to maintenance. Awesome.', '2010-12-02 06:24:07.000000', NULL, 1),
(6241684, 921771, 108069, '<td valign="top">Very clever. Interesting shot. Well done.</td>', 'Very clever. Interesting shot. Well done.', '2010-12-02 06:25:04.000000', NULL, 1),
(6241709, 921163, 108069, '<td valign="top">Great contrast and colors. Nice title. Love the ?s all over. Would have been a good title as well? The negative space is great. Well done.</td>', 'Great contrast and colors. Nice title. Love the ?s all over. Would have been a good title as well? The negative space is great. Well done.', '2010-12-02 07:30:34.000000', NULL, 1),
