(6242244, 921876, 68504, '<td valign="top">Whoa, just right.</td>', 'Whoa, just right.', '2010-12-02 17:31:58.000000', NULL, 1),
(6242245, 921901, 68504, '<td valign="top">Oh, I can hardly bear it.  This is the imagining.</td>', 'Oh, I can hardly bear it.  This is the imagining.', '2010-12-02 17:32:07.000000', NULL, 1),
(6242246, 921719, 68504, '<td valign="top">All the colours of gold with a frisson of trees!</td>', 'All the colours of gold with a frisson of trees!', '2010-12-02 17:32:13.000000', NULL, 1),
(6242247, 921834, 68504, '<td valign="top">Straight to the heart, without any excess.</td>', 'Straight to the heart, without any excess.', '2010-12-02 17:32:19.000000', NULL, 1),
(6242248, 921783, 68504, '<td valign="top">I believe these to be filaments (Yucca filamentosa?) already weaving themselves in an exuberance, an almost frenzy offered by the photographer. I accept.</td>', 'I believe these to be filaments (Yucca filamentosa?) already weaving themselves in an exuberance, an almost frenzy offered by the photographer. I accept.', '2010-12-02 17:32:25.000000', NULL, 1),
(6242249, 921730, 68504, '<td valign="top">but then we shall know face to face.</td>', 'but then we shall know face to face.', '2010-12-02 17:32:32.000000', NULL, 1),
(6242250, 921434, 68504, '<td valign="top">Wonderful and a little frightening such assonance.</td>', 'Wonderful and a little frightening such assonance.', '2010-12-02 17:32:46.000000', NULL, 1),
(6242252, 921983, 68504, '<td valign="top">Capturing the essence. Low down, grit, matrices, crossing crossing... But the blue bag I need to ponder.</td>', 'Capturing the essence. Low down, grit, matrices, crossing crossing... But the blue bag I need to ponder.', '2010-12-02 17:33:00.000000', NULL, 1),
(6242253, 921965, 68504, '<td valign="top">A tree named Alfred E, thinking something powerful. The atom. Gilgamesh.</td>', 'A tree named Alfred E, thinking something powerful. The atom. Gilgamesh.', '2010-12-02 17:33:24.000000', NULL, 1),
(6242254, 921953, 68504, '<td valign="top">Catlike ambiguities: one curtain or two or is cat between or behind or looking fore or aft. A cat is always hidden, no matter how many "eyes" are patterned into the curtain.  Posthumousy feeling of almost but not quite, I must change my life.</td>', 'Catlike ambiguities: one curtain or two or is cat between or behind or looking fore or aft. A cat is always hidden, no matter how many "eyes" are patterned into the curtain.  Posthumousy feeling of almost but not quite, I must change my life.', '2010-12-02 17:33:32.000000', NULL, 1),
(6242255, 921422, 68504, '<td valign="top">About to fall into my hand, some pleasantly weighted round thing, as if expected.</td>', 'About to fall into my hand, some pleasantly weighted round thing, as if expected.', '2010-12-02 17:33:44.000000', NULL, 1),
(6242256, 921981, 68504, '<td valign="top">I want to say "very punny."  Shall I?  Well done and blatant, the plastic, the melamine.</td>', 'I want to say "very punny."  Shall I?  Well done and blatant, the plastic, the melamine.', '2010-12-02 17:33:47.000000', NULL, 1),
