(6242744, 921862, 63812, '<td valign="top">Excellent capture..9</td>', 'Excellent capture..9', '2010-12-02 21:48:19.000000', NULL, 1),
(6242749, 921927, 76335, '<td valign="top">I appreciate the simplicity of interiors, and this is a good example -- nicely balanced and pleasing to the spirit. The shadows and light play off of each other and the rich reds hold it all together. The title, unfortunately, tends to bias the viewer and was probably unnecessary.</td>', 'I appreciate the simplicity of interiors, and this is a good example -- nicely balanced and pleasing to the spirit. The shadows and light play off of each other and the rich reds hold it all together. The title, unfortunately, tends to bias the viewer and was probably unnecessary.', '2010-12-02 21:51:01.000000', NULL, 1),
(6242751, 921758, 76335, '<td valign="top">This is interesting in that it incorporates many different reflections, distortions and abstractions. Good idea.</td>', 'This is interesting in that it incorporates many different reflections, distortions and abstractions. Good idea.', '2010-12-02 21:51:50.000000', NULL, 1),
(6242754, 921875, 76335, '<td valign="top">I don''t care for the vignette/border, but everything inside the frame is terrific -- composition and color work off of each other to good effect.</td>', 'I don''t care for the vignette/border, but everything inside the frame is terrific -- composition and color work off of each other to good effect.', '2010-12-02 21:52:45.000000', NULL, 1),
(6242755, 921917, 76335, '<td valign="top">Beautiful like a painting. A little too conventional for the craziness of this challenge, but I can''t hold a good photograph against you.</td>', 'Beautiful like a painting. A little too conventional for the craziness of this challenge, but I can''t hold a good photograph against you.', '2010-12-02 21:53:08.000000', NULL, 1),
(6242757, 920972, 76335, '<td valign="top">Great composition -- I''m guessing (hoping) this was found and not composed. Not crazy about the orange-ish processing though.</td>', 'Great composition -- I''m guessing (hoping) this was found and not composed. Not crazy about the orange-ish processing though.', '2010-12-02 21:53:45.000000', NULL, 1),
(6242758, 921983, 76335, '<td valign="top">I so wish that bag weren''t blue. The white lines and perpendicular black shadows would play off of each other so nicely otherwise. I''m not sure what story you''re trying to tell. In any case, I''m happy to find my own story.</td>', 'I so wish that bag weren''t blue. The white lines and perpendicular black shadows would play off of each other so nicely otherwise. I''m not sure what story you''re trying to tell. In any case, I''m happy to find my own story.', '2010-12-02 21:54:04.000000', NULL, 1),
(6242762, 921981, 63812, '<td valign="top">lol</td>', 'lol', '2010-12-02 21:57:21.000000', NULL, 1),
(6242773, 921362, 38478, '<td valign="top">Wonderful lines, dramatic clouds, and the birds -- 10 from me</td>', 'Wonderful lines, dramatic clouds, and the birds -- 10 from me', '2010-12-02 22:07:06.000000', NULL, 1),
(6242775, 921424, 38478, '<td valign="top">I love the abstraction to the basic shapes</td>', 'I love the abstraction to the basic shapes', '2010-12-02 22:07:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6242777, 921976, 67697, '<td valign="top">This is fun.  I really like the quirkiness of the shot.  It looks like the one on the left has a Heineken label lol</td>', 'This is fun.  I really like the quirkiness of the shot.  It looks like the one on the left has a Heineken label lol', '2010-12-02 22:09:03.000000', NULL, 1),
(6242778, 921919, 67697, '<td valign="top">This is beautiful.  I love how it looks like one is singing for you.</td>', 'This is beautiful.  I love how it looks like one is singing for you.', '2010-12-02 22:09:44.000000', NULL, 1),
(6242779, 921869, 67697, '<td valign="top">It''s like a stairway to heaven.  Love how the top just disappears.</td>', 'It''s like a stairway to heaven.  Love how the top just disappears.', '2010-12-02 22:10:21.000000', NULL, 1),
(6242782, 921804, 67697, '<td valign="top">Love the top-down view.  I''d like to know how that poor little one got stuck on the bottom.</td>', 'Love the top-down view.  I''d like to know how that poor little one got stuck on the bottom.', '2010-12-02 22:11:15.000000', NULL, 1),
(6242783, 921876, 63812, '<td valign="top">lovely image..9</td>', 'lovely image..9', '2010-12-02 22:11:59.000000', NULL, 1),
(6242785, 921934, 63812, '<td valign="top">amazing...10</td>', 'amazing...10', '2010-12-02 22:14:35.000000', NULL, 1),
(6242789, 921951, 63812, '<td valign="top">I love this..9</td>', 'I love this..9', '2010-12-02 22:15:16.000000', NULL, 1),
(6242791, 921580, 67697, '<td valign="top">This is one of my faves of the challenge.  I had one interpretation and then I looked up the word to see if it fit.  Now I just see that confession can lead to a sense of doom - as opposed to the intention of leading towards grace.  Interesting.</td>', 'This is one of my faves of the challenge.  I had one interpretation and then I looked up the word to see if it fit.  Now I just see that confession can lead to a sense of doom - as opposed to the intention of leading towards grace.  Interesting.', '2010-12-02 22:16:21.000000', NULL, 1),
(6242795, 921934, 67697, '<td valign="top">Some will say that it doesn''t quite fit a PH challenge, and maybe it doesn''t because it''s too clean lol.  But you are a master in your creations.  I love how you created a story here that is abstract in a way.  And I would love it if someone presented my champagne this way :D</td>', 'Some will say that it doesn''t quite fit a PH challenge, and maybe it doesn''t because it''s too clean lol.  But you are a master in your creations.  I love how you created a story here that is abstract in a way.  And I would love it if someone presented my champagne this way :D', '2010-12-02 22:18:13.000000', NULL, 1),
(6242802, 921951, 67697, '<td valign="top">Here''s a shot I don''t get - I''m just not a deep thinker.  I like it tho - because it makes me wonder what is going on.</td>', 'Here''s a shot I don''t get - I''m just not a deep thinker.  I like it tho - because it makes me wonder what is going on.', '2010-12-02 22:22:55.000000', NULL, 1),
(6242804, 921862, 67697, '<td valign="top">I like this for the mood that it evokes.  Kind of one where you can see yourself getting lost in the moment and thinking about life.  And hoping you don''t lose that umbrella :D</td>', 'I like this for the mood that it evokes.  Kind of one where you can see yourself getting lost in the moment and thinking about life.  And hoping you don''t lose that umbrella :D', '2010-12-02 22:23:55.000000', NULL, 1),
(6242805, 921928, 67697, '<td valign="top">I really love your use of light and shadow.  The details on the white flower petals are pretty.</td>', 'I really love your use of light and shadow.  The details on the white flower petals are pretty.', '2010-12-02 22:25:02.000000', NULL, 1),
(6242807, 921930, 67697, '<td valign="top">I love how everything but the man and keys are blurred.  Now I have that song in my head - thanks!  :)</td>', 'I love how everything but the man and keys are blurred.  Now I have that song in my head - thanks!  :)', '2010-12-02 22:25:50.000000', NULL, 1),
(6242809, 921981, 67697, '<td valign="top">I thought this was very funny.  That looks so tasty too!</td>', 'I thought this was very funny.  That looks so tasty too!', '2010-12-02 22:26:29.000000', NULL, 1),
(6242811, 920972, 67697, '<td valign="top">What an interesting find.  This shot makes me want to hear the story.</td>', 'What an interesting find.  This shot makes me want to hear the story.', '2010-12-02 22:27:21.000000', NULL, 1),
(6242814, 921900, 76335, '<td valign="top">A powerful effect incongruous with your humdrum subject.</td>', 'A powerful effect incongruous with your humdrum subject.', '2010-12-02 22:29:03.000000', NULL, 1),
(6242816, 921875, 67697, '<td valign="top">like wabi-sabi?  i like how it looks like flowers in front of a painted backdrop.  looks almost like a movie screen.</td>', 'like wabi-sabi?  i like how it looks like flowers in front of a painted backdrop.  looks almost like a movie screen.', '2010-12-02 22:29:42.000000', NULL, 1),
(6242817, 921806, 67697, '<td valign="top">i''m not sure how this is being received but I love it.  there''s so much fun and quirkiness here.  she''s got to be a lot of fun :)</td>', 'i''m not sure how this is being received but I love it.  there''s so much fun and quirkiness here.  she''s got to be a lot of fun :)', '2010-12-02 22:30:28.000000', NULL, 1),
(6242820, 921772, 67697, '<td valign="top">hmmm woman carrying doll or man about to lose his pants.  i''m not sure which one intrigues me more.</td>', 'hmmm woman carrying doll or man about to lose his pants.  i''m not sure which one intrigues me more.', '2010-12-02 22:31:42.000000', NULL, 1),
(6242824, 921889, 76335, '<td valign="top">Pinhole? In any case, I love how this is reduced to lines and a few suggestive shapes. Also, it looks like you or your subject was in motion as I see some motion blur. It adds some welcome energy, gravity. Excellent.</td>', 'Pinhole? In any case, I love how this is reduced to lines and a few suggestive shapes. Also, it looks like you or your subject was in motion as I see some motion blur. It adds some welcome energy, gravity. Excellent.', '2010-12-02 22:32:12.000000', NULL, 1),
(6242826, 920914, 76335, '<td valign="top">Photopointilism? Reduced to warm colors and soft shadows and points of light, your subject is quite beautifully rendered.</td>', 'Photopointilism? Reduced to warm colors and soft shadows and points of light, your subject is quite beautifully rendered.', '2010-12-02 22:33:04.000000', NULL, 1),
(6242827, 921424, 76335, '<td valign="top">The eye bounces around the composition finding seemingly many paths to escape -- but they''re all dead ends. Wonderfully labyrinthic.</td>', 'The eye bounces around the composition finding seemingly many paths to escape -- but they''re all dead ends. Wonderfully labyrinthic.', '2010-12-02 22:33:50.000000', NULL, 1),
(6242830, 921976, 76335, '<td valign="top">Who can resist this fairy tale? Who would want to? One of those images I wish I could climb into and explore. Alas, it''s futile -- like revisiting one''s childhood. My pick of the <strike>evening</strike> challenge.</td>', 'Who can resist this fairy tale? Who would want to? One of those images I wish I could climb into and explore. Alas, it''s futile -- like revisiting one''s childhood. My pick of the evening challenge.', '2010-12-02 22:34:25.000000', NULL, 1),
(6242833, 921513, 76335, '<td valign="top">Awesome. Any further attempt at words will ruin it for me. This goes high on my list. <br/> <br/>A ten for you (one of two I''ve handed out).</td>', 'Awesome. Any further attempt at words will ruin it for me. This goes high on my list.  A ten for you (one of two I''ve handed out).', '2010-12-02 22:35:04.000000', NULL, 1),
