(6242841, 921951, 38032, '<td valign="top">An interesting setup.  Very flat yet interesting composition and artsy vibe.</td>', 'An interesting setup.  Very flat yet interesting composition and artsy vibe.', '2010-12-02 22:36:13.000000', NULL, 1),
