(6243305, 921976, 15711, '<td valign="top">voters are dumb.</td>', 'voters are dumb.', '2010-12-03 08:23:14.000000', NULL, 0),
(6243309, 921798, 30364, '<td valign="top">Thank you for the very kind mention in your Photographer''s Comments, Richard.  I have been genuinely enthralled by some of your recent stuff.  Inspired too.  And I could not be more delighted to see your Posthumous Blue.  I think it''s especially great that you are doing this kind of work lately because, unlike me, you have something to lose!  I never was much good so it doesn''t matter to me if I crash &amp; burn score-wise.</td>', 'Thank you for the very kind mention in your Photographer''s Comments, Richard.  I have been genuinely enthralled by some of your recent stuff.  Inspired too.  And I could not be more delighted to see your Posthumous Blue.  I think it''s especially great that you are doing this kind of work lately because, unlike me, you have something to lose!  I never was much good so it doesn''t matter to me if I crash & burn score-wise.', '2010-12-03 08:25:54.000000', NULL, 0),
(6243319, 921910, 30364, '<td valign="top">Now that I look at it again I see people dancing.  Sort of stick people.  They must be celebrating your success, Lev!  Congrats.<br/> <br/>And I loved this comment from <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30982" rel="nofollow" target="_blank">Melethia</a>: " Wonderfully woven warmth!"  That is so <i>very</i> good, isn''t it?  Well done for the image and for inspiring that perfect comment.</td>', 'Now that I look at it again I see people dancing.  Sort of stick people.  They must be celebrating your success, Lev!  Congrats. And I loved this comment from  Melethia: " Wonderfully woven warmth!"  That is so very good, isn''t it?  Well done for the image and for inspiring that perfect comment.', '2010-12-03 08:30:46.000000', NULL, 0),
(6243330, 921876, 30364, '<td valign="top">Knew it.  Had to be you.</td>', 'Knew it.  Had to be you.', '2010-12-03 08:38:09.000000', NULL, 0),
